一、繪製自製暗箱 
 透過線上3D 繪圖軟體Tinkercad 繪製暗箱，並列印成品(圖1-1、1-2、1-3、1-4) 

二、程式碼 
上網查詢各sensor 的Arduino 程式，一一檢測，最後合併成實驗所需的程式碼如下: 


#include <dht.h> 
 #include <OneWire.h> 
 #include <DallasTemperature.h> 
 #include <SoftwareSerial.h> 

 SoftwareSerial SerialCom (A4,A3); 
 byte addArray[] = { 0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79 }; 
 char dataValue[9]; 
 String dataString = ""; 

 #define dht_dpin A5 //定義訊號要從Pin A5 進來 
 #define DHT22 22 
 #define offset 0.18 
dht DHT; 

 #define ONE_WIRE_BUS 2 // DS18B20 connect to Pin 2 
OneWire oneWire(ONE_WIRE_BUS); 
 DallasTemperature sensors(&oneWire); 
double WTval; 
 double RTval_read; 
 double RTval; 
 double PHval_read; 
 double PHval; 
 double Ph7Buffer = 6.86; // For PH7 buffer solution's PH value , 7 or 6.86 
 double Ph4Buffer = 4.01; // For PH4 buffer solution's PH value , 4 or 4.01 
 double Ph7Reading = 656; // For PH7 buffer solution's PH value , 7 or 6.86 
 double Ph4Reading = 748; // PH4 Buffer Solution Reading. 
 double PhRatio = 0; // PH Step 
 const int gasSensor =0; 

void setup(){ 
 Serial.begin(9600); 
 SerialCom.begin(9600); 
 PhRatio = (Ph4Buffer - Ph7Buffer) / (Ph4Reading - Ph7Reading); 
 Serial.println("Starting"); 
 sensors.begin();} 

void loop(){ 
 DHT.read22(dht_dpin); //去程式庫裡面找DHT.read22 
 Serial.print("Humidity= "); 
 Serial.print(DHT.humidity); 
 Serial.print("% "); 
 Serial.print("temperature= "); 
 Serial.print(DHT.temperature); 
 Serial.print("C"); 
 sensors.requestTemperatures(); 
 WTval = sensors.getTempCByIndex(0); 
 RTval_read = analogRead(1); 
 RTval = (double) RTval_read / 3.4 * (5/10.24); 
 PHval_read = analogRead(2); 
 PHval = (PHval_read - Ph7Reading) * PhRatio + Ph7Buffer; 
 Serial.print(" "); 
 Serial.print("Water Temperature: "); 
 Serial.print(WTval, 1); 
 Serial.print(" "); 
 Serial.print("Room Temperature: "); 
 Serial.print(RTval, 1); 
 Serial.print(" "); 
 Serial.print("PH read value: "); 
 Serial.print(PHval_read, 0); 
 Serial.print(" "); 
 Serial.print("PH value: "); 
 Serial.print(PHval, 1); 
 float voltage; 
 voltage= getVoltage(gasSensor); 
 Serial.print(" O3: "); 
 Serial.print(voltage); 
 Serial.print(" voltage"); 
 SerialCom.write(addArray, 9); 
 SerialCom.readBytes(dataValue, 9); 
 int resHigh = (int) dataValue[2]; 
 int resLow = (int) dataValue[3]; 
 int pulse = (256*resHigh)+resLow; 
 dataString = String(pulse); 
 Serial.print(" CO2: "); 
 Serial.print(pulse); 
 Serial.println(" PPM"); 
delay(3000);//每3000ms 更新一次} 
 float getVoltage(int pin) { 
 return (analogRead(pin) * 0.004882814); } 

